PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?variant ?template ?query WHERE {
  ?variant smtg:hasTemplateRequirement/smtg:requiresTemplate ?t . ?t rdfs:label ?template . OPTIONAL { ?t smtg:templateQuery ?query }
}

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?printing ?set ?printedName ?printedText WHERE {
  ?card a smtg:OracleCard ; smtg:name "Lightning Bolt" .
  ?printing smtg:isPrintingOf ?card ; smtg:inLanguage <https://w3id.org/smtg/vocab/language/it> ;
            smtg:inSet/smtg:setCode ?set ; smtg:hasPrintedFace ?pf .
  ?pf smtg:hasPrintedText ?n . ?n a smtg:PrintedName ; smtg:textValue ?printedName .
  OPTIONAL { ?pf smtg:hasPrintedText ?t . ?t a smtg:PrintedRulesText ; smtg:textValue ?printedText . }
}

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?faceName ?kind WHERE {
  { ?f smtg:hasNoManaCost true ; smtg:name ?faceName . BIND("no mana cost" AS ?kind) }
  UNION
  { ?f smtg:hasManaCost/smtg:manaCostNotation "{0}" ; smtg:name ?faceName . BIND("cost {0}" AS ?kind) }
} ORDER BY ?kind ?faceName

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?faceName ?power ?toughness WHERE {
  ?f smtg:name ?faceName ; smtg:powerText ?power ; smtg:toughnessText ?toughness .
  FILTER NOT EXISTS { ?f smtg:powerValue ?pv . ?f smtg:toughnessValue ?tv . }
} ORDER BY ?faceName

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?tag (COUNT(?parent) AS ?parents) (GROUP_CONCAT(?pl; separator=', ') AS ?parentLabels) WHERE {
  ?t smtg:taggerParent ?parent ; skos:prefLabel ?tag . OPTIONAL { ?parent skos:prefLabel ?pl }
} GROUP BY ?tag HAVING (COUNT(?parent) > 1) ORDER BY DESC(?parents) ?tag

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?a ?target WHERE {
  ?a a smtg:ArtTagAssignment ; smtg:assignmentTarget ?target . FILTER NOT EXISTS { ?target a smtg:Illustration }
}
